Definition sr_postv (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res b : Z) (es : list mbe) (insz n x lo : Z) (beg bpos lpos : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 40)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' res (SrCells b beg (b + 8) bpos lpos)
    /\ AMBmid m' b es insz n x
    /\ ACONST m'.

Definition sr_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res b : Z) (es : list mbe) (insz n x lo : Z) (m : mem) : machine_state -> Prop :=
  sr_postv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res b es insz n x lo
    (mb_mid_out b es insz x) (mb_outpos es insz) (mb_mid_outend es insz n) m.

Definition sr_stmt : Prop := forall (res b : Z) (es : list mbe) (insz n x lo : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AMBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  rw_cells bsegs m res [CB 40 rj] ->
  stk bsegs m lo (bv_unsigned sp) -> lo + MB_SR_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m ->
  aapp res 40 -> res mod 8 = 0 -> accessible m res 40 -> shvis m res (res + 40) ->
  mb_off b (mb_put_es es insz n x) res 40 ->
  evt bsegs (sr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res b es insz n x lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz b) (wz insz) (wz n) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_MB_SUBRANGE_CTOR) fc None m (seg_rom bsegs)).

