Section SRT.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (res b : Z) (es : list mbe) (insz n x lo : Z) (m0 : mem).
  Hypothesis MID : AMBmid m0 b es insz n x.
  Hypothesis N1 : 1 <= n.
  Hypothesis NB : 0 <= insz /\ insz + n <= 2^30.
  Hypothesis LO : lo + MB_SR_STACK <= bv_unsigned sp.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis AC : ACONST m0.
  Hypothesis RAP : aapp res 40.
  Hypothesis RAL : res mod 8 = 0.
  Hypothesis RACC : accessible m0 res 40.
  Hypothesis ROFF : mb_off b (mb_put_es es insz n x) res 40.

  Let W : list (Z * Z) := [(lo, bv_unsigned sp); (res, res + 40)]%Z.

  Lemma sr_FWM : Forall (mwin b (mb_put_es es insz n x)) W.
  Proof. unfold W. apply mwin_two; [exact (AMBraw_addr_ok _ _ _ _ _ _ _ MID)| exact CEIL| exact RAP| lia| exact ROFF]. Qed.

  Lemma sr_FW : Forall awin W.
  Proof. exact (mwin_awin _ _ _ sr_FWM). Qed.

