  Variable j0 : list byte.
  Definition sr_frame (m : mem) : Prop :=
    rw_cells bsegs m (bv_unsigned sp + -64) [CB 8 j0; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  (* [comment removed for export] *)
  Lemma sr_epi : forall (m1 : mem) (beg bpos lpos : Z)
      (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 s0' s1' s2' s3' s4' s5' : word),
    munch W m0 m1 -> wmono bsegs m0 m1 -> mem_inv bsegs m1 ->
    sr_frame m1 -> stk bsegs m1 lo (bv_unsigned sp + -64) ->
    rw_cells bsegs m1 res [C8 (Z_to_bv 64 b)] ->
    rw_cells bsegs m1 (res + 8) [C8 (Z_to_bv 64 beg); C8 (Z_to_bv 64 (b + 8))] ->
    rw_cells bsegs m1 (res + 24) [C8 (Z_to_bv 64 bpos); C8 (Z_to_bv 64 lpos)] ->
    evt bsegs (sr_postv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res b es insz n x lo beg bpos lpos m0)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0' s1' a0 a1 a2 a3 a4 a5 a6 a7 s2' s3' s4' s5' s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 0xc1fe8) fc None m1 (seg_rom bsegs)).
