  (* [comment removed for export] *)
  Lemma sr_tail3 : forall (m1 : mem) (xl sl prvl xn g op oe : Z) (jl : list byte) (z16 j16 : list byte)
      (rax t0 t1 t2 a3v a6v a7 t3 t4 t5 t6 : word),
    munch W m0 m1 -> wmono bsegs m0 m1 -> mem_inv bsegs m1 ->
    sr_frame m1 -> stk bsegs m1 lo (bv_unsigned sp + -64) ->
    rw_cells bsegs m1 res [C8 (Z_to_bv 64 b)] ->
    rw_cells bsegs m1 (res + 8) [CB 16 z16] -> rw_cells bsegs m1 (res + 24) [CB 16 j16] ->
    In (xl, sl) (mb_put_es es insz n x) -> In (xn, g) (mb_put_es es insz n x) -> xl <> xn ->
    rw_cells bsegs m1 xl [C8 (Z_to_bv 64 xn); C8 (Z_to_bv 64 prvl)] ->
    rw_cells bsegs m1 (xl + 16) [C8 (Z_to_bv 64 sl); CB (Z.to_nat (mb_block_size sl - 24)) jl] ->
    rw_cells bsegs m1 xn [C8 (Z_to_bv 64 (b + 8)); C8 (Z_to_bv 64 xl)] ->
    0 <= op -> op < sl -> sl - op < n -> oe = n - (sl - op) -> sl < 2^62 -> n < 2^62 ->
    evt bsegs (sr_postv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res b es insz n x lo xl op oe m0)
      (sr_st P_A_SR_LOOP1 rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 res b n op xl xn oe a3v a6v a7
